import pandas as pd
import numpy as np


def _plan_eq(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim = inputs['DIM_ACCOUNT'].copy()
    stg = inputs['STG_ACCOUNT'].copy()

    # Normalize date columns to Timestamp (keep NaT for nulls)
    if 'eff_start_date' in dim.columns:
        dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
    if 'eff_end_date' in dim.columns:
        dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    if 'update_date' in stg.columns:
        stg['update_date'] = pd.to_datetime(stg['update_date'])

    # Build in-memory state: account_id -> list of version dicts
    state = {}
    for _, row in dim.iterrows():
        acc = row['account_id']
        state.setdefault(acc, []).append({
            'plan': row['plan'],
            'eff_start_date': row['eff_start_date'],
            'eff_end_date': row['eff_end_date'],
            'is_current': row['is_current'],
        })

    for acc in state:
        state[acc].sort(key=lambda v: v['eff_start_date'])

    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='mergesort')

    for _, s in stg_sorted.iterrows():
        acc = s['account_id']
        plan = s['plan']
        upd = s['update_date']

        versions = state.get(acc)

        if not versions:
            state[acc] = [{
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            }]
            continue

        # find version covering upd
        v = None
        for ver in versions:
            start = ver['eff_start_date']
            end = ver['eff_end_date']
            if start <= upd and (pd.isna(end) or upd < end):
                v = ver
                break

        if v is None:
            # earlier than earliest existing version
            f = min(versions, key=lambda x: x['eff_start_date'])
            new_ver = {
                'plan': plan,
                'eff_start_date': upd,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            }
            versions.append(new_ver)
            versions.sort(key=lambda x: x['eff_start_date'])
        else:
            if _plan_eq(v['plan'], plan):
                # no-op
                pass
            elif upd == v['eff_start_date']:
                v['plan'] = plan
            else:
                new_ver = {
                    'plan': plan,
                    'eff_start_date': upd,
                    'eff_end_date': v['eff_end_date'],
                    'is_current': v['is_current'],
                }
                v['eff_end_date'] = upd
                v['is_current'] = 0
                versions.append(new_ver)
                versions.sort(key=lambda x: x['eff_start_date'])

    rows = []
    for acc, versions in state.items():
        for ver in versions:
            rows.append({
                'account_id': acc,
                'plan': ver['plan'],
                'eff_start_date': ver['eff_start_date'],
                'eff_end_date': ver['eff_end_date'],
                'is_current': ver['is_current'],
            })

    out = pd.DataFrame(rows, columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'])

    if not out.empty:
        out = out.sort_values(['account_id', 'eff_start_date'], kind='mergesort').reset_index(drop=True)
        out['account_id'] = out['account_id'].astype(dim['account_id'].dtype if 'account_id' in dim.columns else np.int64)
        out['is_current'] = out['is_current'].astype(np.int64)
    else:
        out = pd.DataFrame(columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'])

    return {'dim_account_out': out}
